theorem extracted_1.{u} {G Ω₀ : Type u} [inst : MeasureableFinGroup G] [inst_1 : MeasureSpace Ω₀]
  (p : multiRefPackage G Ω₀) (Ω : Fin p.m → Type u) (hΩ : (i : Fin p.m) → MeasureSpace (Ω i))
  (hΩprob : ∀ (i : Fin p.m), IsProbabilityMeasure ℙ) (X : (i : Fin p.m) → Ω i → G)
  (hmeasX : ∀ (i : Fin p.m), Measurable (X i)) (h_min : multiTauMinimizes p Ω hΩ X) (Ω' : Fin p.m → Type u)
  (hΩ' : (i : Fin p.m) → MeasureSpace (Ω' i)) (hΩ'prob : ∀ (i : Fin p.m), IsProbabilityMeasure ℙ)
  (X' : (i : Fin p.m) → Ω' i → G) (hmeasX' : ∀ (i : Fin p.m), Measurable (X' i)) {S : Type u}
  [inst_2 : MeasurableSpace S] [inst_3 : MeasurableSingletonClass S] (Y : (i : Fin p.m) → Ω' i → S)
  (hY : ∀ (i : Fin p.m), Measurable (Y i)) (φ : Equiv.Perm (Fin p.m)) :
  let Xφ := fun i => X (φ i);
  let Ωφ := fun i => Ω (φ i);
  let hΩφ := fun i => hΩ (φ i);
  let hΩφprob := ⋯;
  let hmeasXφ := ⋯;
  p.η * ∑ i : Fin p.m, d[Xφ i # p.X₀] = p.η * ∑ i : Fin p.m, d[X i # p.X₀] := by
  congr 1
          exact Fintype.sum_equiv φ _ _ fun _ ↦ rfl

theorem extracted_1.{u} {G Ω₀ : Type u} [inst : MeasureableFinGroup G] [inst_1 : MeasureSpace Ω₀]
  (p : multiRefPackage G Ω₀) (Ω : Fin p.m → Type u) (hΩ : (i : Fin p.m) → MeasureSpace (Ω i))
  (hΩprob : ∀ (i : Fin p.m), IsProbabilityMeasure ℙ) (X : (i : Fin p.m) → Ω i → G)
  (hmeasX : ∀ (i : Fin p.m), Measurable (X i)) (h_min : multiTauMinimizes p Ω hΩ X) (Ω' : Fin p.m → Type u)
  (hΩ' : (i : Fin p.m) → MeasureSpace (Ω' i)) (hΩ'prob : ∀ (i : Fin p.m), IsProbabilityMeasure ℙ)
  (X' : (i : Fin p.m) → Ω' i → G) (hmeasX' : ∀ (i : Fin p.m), Measurable (X' i)) {S : Type u}
  [inst_2 : MeasurableSpace S] [inst_3 : MeasurableSingletonClass S] (Y : (i : Fin p.m) → Ω' i → S)
  (hY : ∀ (i : Fin p.m), Measurable (Y i)) (φ : Equiv.Perm (Fin p.m)) :
  let Xφ := fun i => X (φ i);
  let Ωφ := fun i => Ω (φ i);
  let hΩφ := fun i => hΩ (φ i);
  let hΩφprob := ⋯;
  let hmeasXφ := ⋯;
  D[Xφ ; hΩφ] = D[X ; hΩ] := by
  exact multiDist_of_perm hΩ hΩprob X φ

@[gcongr]
theorem mul_le_mul_of_nonneg_left [PosMulMono α] (h : b ≤ c) (a0 : 0 ≤ a) : a * b ≤ a * c :=
  @CovariantClass.elim α≥0 α (fun x y => x * y) (· ≤ ·) _ ⟨a, a0⟩ _ _ h

